  FlnQuestionSpec(106, 'DIV', 'DIV2', 'ભાગાકાર કરો. (પ્રશ્ન - 2) એક અંકનો એક અંક સાથે ભાગાકાર.', '1d ÷ 1d, exact integer'),
  FlnQuestionSpec(107, 'DIV', 'DIV3', 'ભાગાકાર કરો. (પ્રશ્ન - 3) બે અંકનો એક અંક સાથે ભાગાકાર.', '2d ÷ 1d, exact integer'),
  FlnQuestionSpec(108, 'DIV', 'DIV4', 'ભાગાકાર કરો. (પ્રશ્ન - 4) બે અંકનો એક અંક સાથે ભાગાકાર.', '2d ÷ 1d, exact integer'),
  FlnQuestionSpec(109, 'DIV', 'DIV5', 'ભાગાકાર કરો. (પ્રશ્ન - 5) બે અંકનો એક અંક સાથે ભાગાકાર.', '2d ÷ 1d, exact integer'),
  FlnQuestionSpec(110, 'DIV', 'DIV6', 'ભાગાકાર કરો. (પ્રશ્ન - 6) ત્રણ અંકનો ભાગાકાર.', '3d ÷ divisor, exact integer'),
  FlnQuestionSpec(111, 'DIV', 'DIV7', 'ભાગાકાર કરો. (પ્રશ્ન - 7) ત્રણ અંકનો ભાગાકાર.', '3d ÷ divisor, exact integer'),
  FlnQuestionSpec(112, 'DIV', 'DIV8', 'ભાગાકાર કરો. (પ્રશ્ન - 8) ચાર અંકનો ભાગાકાર.', '4d ÷ divisor, exact integer'),
  FlnQuestionSpec(113, 'DIV', 'DIV9', 'ભાગાકાર કરો. (પ્રશ્ન - 9) ચાર અંકનો બે અંક સાથે ભાગાકાર.', '4d ÷ 2d (10–19), exact integer'),
  FlnQuestionSpec(114, 'DIV', 'DIV10', 'ભાગાકાર કરો. (પ્રશ્ન - 10) ચાર અંકનો બે અંક સાથે ભાગાકાર.', '4d ÷ 2d (10–19), exact integer'),
  FlnQuestionSpec(115, 'DIV', 'DIV11', 'ભાગાકાર કરો. (પ્રશ્ન - 11) ચાર અંકનો બે અંક સાથે ભાગાકાર.', '4d ÷ 2d (10–19), exact integer'),
  FlnQuestionSpec(116, 'DIV', 'DIV12', 'ભાગાકાર કરો. (પ્રશ્ન - 12) ચાર અંકનો બે અંક સાથે ભાગાકાર.', '4d ÷ 2d (10–19), exact integer'),
  FlnQuestionSpec(117, 'DIV', 'DIV13', 'ભાગાકાર કરો. (પ્રશ્ન - 13) પાંચ અંકનો બે અંક સાથે ભાગાકાર.', '5d ÷ 2d (10–19), exact integer'),
  FlnQuestionSpec(118, 'DIV', 'DIV14', 'ભાગાકાર કરો. (પ્રશ્ન - 14) પાંચ અંકનો બે અંક સાથે ભાગાકાર.', '5d ÷ 2d (10–19), exact integer'),
  FlnQuestionSpec(119, 'DIV', 'DIV15', 'ભાગાકાર કરો. (પ્રશ્ન - 15) પાંચ અંકનો બે અંક સાથે ભાગાકાર.', '5d ÷ 2d (10–19), exact integer'),
  FlnQuestionSpec(120, 'WP', 'WP1', 'એક દુકાનદારે સવારે {n1} પેન્સિલો અને સાંજે {n2} પેન્સિલો વહેંચી હતી. તો કુલ કેટલી પેન્સિલો વેચાઈ હતી?', 'Q120 = n1 + n2'),
  FlnQuestionSpec(121, 'WP', 'WP2', 'દ્વિજ પાસે {n1} લખોટીઓ હતી. તેણે {n2} લખોટીઓ મિષ્ટીને આપી દીધી. હવે દ્વિજ પાસે કેટલી લખોટીઓ બાકી રહેશે?', 'Q121 = n1 - n2 (n1 > n2)'),
  FlnQuestionSpec(122, 'WP', 'WP3', 'મિષ્ટી પાસે {n1} પેટીઓ છે, દરેક પેટીમાં {n2} રબ્બર બેન્ડ છે. તો મિષ્ટીપાસે કુલ કેટલા રબ્બર બેન્ડ હશે?', 'Q122 = n1 × n2 (n2 in 2..9)'),
  FlnQuestionSpec(123, 'WP', 'WP4', 'એક બોક્સમાં {n1} મીઠાઈઓ છે, જો આ મીઠાઇ {n2} બાળકોમાં સમાન રીતે વહેંચવામાં આવે છે. દરેક બાળકને કેટલી મીઠાઈ મળે છે?', 'Q123 = n1 / n2 (exact integer)'),
  FlnQuestionSpec(124, 'WP', 'WP5', 'એક ખેડૂતે તેના ખેતરમાંથી સોમવારે {n1} મંગળવારે {n2} અને બુધવારે {n3} કેરીઓ ચૂંટી હતી. તેણે કુલ કેટલી કેરીઓ ચૂંટી હતી?', 'Q124 = n1 + n2 + n3'),
  FlnQuestionSpec(125, 'WP', 'WP6', 'એક ટાંકીમાં {n1} લિટર પાણી હતું. {n2} લિટર કપડાં ધોવા માટે અને {n3} લિટર સાફસફાઇ માટે વપરાય છે. તો હવે ટાંકીમાં કેટલું પાણી બાકી છે?', 'Q125 = n1 - n2 - n3 (> 0)'),
  FlnQuestionSpec(126, 'WP', 'WP7', 'એક પાટિયા ઉપર {n1} ચોકલેટ્સની {n2} હરોળમાં ગોઠવવામાં આવે છે. જો તે {n3} ચોકલેટના બોક્સમાં પેક કરવામાં આવે, તો કેટલા બોક્સની જરૂર પડશે?', 'Q126 = (n1 × n2) / n3 (exact integer)'),
  FlnQuestionSpec(127, 'WP', 'WP8', 'એક પુસ્તકાલયમાં {n1} વાર્તાના પુસ્તકો હતા. બીજા {n2} પુસ્તકો ઉમેરવામાં આવ્યા, પછી {n3} પુસ્તકો બીજી પુસ્તકાલયમાં આપવામાં આવ્યા. કેટલા પુસ્તકો બાકી છે?', 'Q127 = (n1 + n2) - n3 (> 0)'),
  FlnQuestionSpec(128, 'WP', 'WP9', 'એક ખેડૂત પાસે {n1} મરઘીઓ છે. તેણે વધુ {n2} મરઘીઓ ખરીદી, પણ {n3} મરઘીઓ ભાગી ગઈ. જો બાકી રહેલી દરેક મરઘી {n4} ઇંડા આપે, તો કુલ કેટલા ઇંડા થાય?', 'Q128 = ((n1 + n2) - n3) × n4'),
  FlnQuestionSpec(129, 'WP', 'WP10', 'એક પૂજારી {n1} ફૂલ લઈને ઘરેથી મંદિરે જવા માટે નીકળે છે. રસ્તામાંથી તેણે બીજા {n2} ફૂલ ઉતાર્યા તેમાંથી પહેલાં મંદિરે તેણે {n3} ફૂલ ભગવાનને અર્પણ કર્યા. હવે એક ચમત્કાર થયો, તે પૂજારી પાસે થેલીમાં જેટલા ફૂલ વધ્યા હતા તેના કરતાં {n4} ગણા ફૂલ થઈ ગયા. જો આ પૂજારીને {n5} મંદિરમાં સમાન ભાગે ફૂલ અર્પણ કરવા હોય તો દરેક મંદિરમાં કેટલા ફૂલ અર્પણ કરવા પડે?', 'Q129 = (((n1 + n2) - n3) × n4) / n5 (exact integer)'),
  FlnQuestionSpec(130, 'WP', 'WP11', 'હેતાક્ષ પાસે {n1} લખોટી છે. હવે જો હેતાક્ષ ધ્રેયાંશીને {n2} લખોટી આપે અને જે બાકી રહે તેમાંથી {n3} ભાગની લખોટી દ્વિજને આપે છે. પછી મિષ્ટી હેતાક્ષ પાસે જેટલી લખોટી છે તેના કરતાં {n4} ગણી લખોટી હેતાક્ષને આપે છે. ત્યારબાદ યજ્ઞા પણ હેતાક્ષને {n5} લખોટી આપે છે તો હવે હેતાક્ષ પાસે કુલ કેટલી લખોટી થશે?', 'Q130 = ((n1-n2)-(n1-n2)/n3) × (1+n4) + n5 (with ordinal Q130_V3)'),
];
